import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val n = BufferedReader(InputStreamReader(System.`in`)).readLine().trim().toInt()
    val mod = 1_000_003L

    if (n == 0) {
        print(1)
        return
    }

    var result = 1L
    repeat(n - 1) {
        result = result * 3 % mod
    }
    print(result)
}
